"use client"

/** KPI strip meant to sit above a table. Figures come from stat-strip. */

import * as React from "react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { sparklinePoints } from "@/lib/data-table-reorder"
import { StatStrip, type StatStripItem, type StatStripProps } from "@/components/ui/stat-strip"

export type TableSummaryItem = StatStripItem & {
  sparkline?: readonly number[]
  /** Names the trend. Required when a sparkline is set, so the line is not the only signal. */
  sparklineLabel?: string
}

export type TableSummaryStripLabels = {
  loading?: string
  retry?: string
}

export type TableSummaryStripProps = Omit<StatStripProps, "items" | "renderExtra"> & {
  items?: readonly TableSummaryItem[]
  loading?: boolean
  /** Replaces the figures with an alert and an optional retry. */
  error?: string
  onRetry?: () => void
  /**
   * `hide` removes the strip when there are no items, or every value is empty.
   * `show` keeps explicit zeros on screen.
   */
  empty?: "hide" | "show"
  /** Optional slot under each item, beside the sparkline when one is set. */
  renderItem?: (item: TableSummaryItem) => React.ReactNode
  labels?: TableSummaryStripLabels
}

function isBlank(item: TableSummaryItem) {
  if (item.sparkline?.some((value) => value !== 0)) return false
  if (typeof item.value === "number") return item.value === 0 && !item.delta
  const text = String(item.value).trim()
  return text === "" || text === "0"
}

function SummarySparkline({ values, label }: { values: readonly number[]; label: string }) {
  const points = sparklinePoints(values, 72, 20)
  if (!points) return null
  return (
    <svg viewBox="0 0 72 20" role="img" aria-label={label} className="h-5 w-16 max-w-full text-primary">
      <polyline points={points} fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  )
}

export function TableSummaryStrip({
  items = [],
  loading = false,
  error,
  onRetry,
  empty = "hide",
  renderItem,
  labels,
  variant = "inline",
  locale = "en-US",
  className,
  classNames,
}: TableSummaryStripProps) {
  const loadingLabel = labels?.loading ?? "Loading"
  const retryLabel = labels?.retry ?? "Retry"
  const blank = items.length === 0 || items.every(isBlank)
  const hide = !loading && !error && empty === "hide" && blank

  if (hide) return null

  if (loading) {
    const count = Math.max(items.length, 3)
    return (
      <div
        data-slot="table-summary-strip"
        data-state="loading"
        role="status"
        aria-busy="true"
        aria-live="polite"
        className={cn("flex min-w-0 max-w-full flex-wrap gap-x-6 gap-y-3", className)}
      >
        <p className="w-full text-sm text-muted-foreground">{loadingLabel}</p>
        {Array.from({ length: count }, (_, index) => (
          <div key={index} className="min-w-0 basis-36">
            <Skeleton aria-hidden className="h-3 w-16 motion-reduce:animate-none" />
            <Skeleton aria-hidden className="mt-2 h-8 w-24 motion-reduce:animate-none" />
          </div>
        ))}
      </div>
    )
  }

  if (error) {
    return (
      <div data-slot="table-summary-strip" data-state="error" role="alert" className={cn("flex min-w-0 max-w-full flex-wrap items-center gap-2", className)}>
        <p className="min-w-0 text-sm text-destructive">{error}</p>
        {onRetry ? (
          <Button type="button" size="sm" variant="outline" onClick={onRetry}>
            {retryLabel}
          </Button>
        ) : null}
      </div>
    )
  }

  return (
    <div data-slot="table-summary-strip" data-state={blank ? "empty" : "filled"} className="min-w-0 max-w-full">
      <StatStrip
        items={items}
        variant={variant}
        locale={locale}
        className={className}
        classNames={{
          ...classNames,
          item: cn("max-w-full", classNames?.item),
        }}
        renderExtra={(item) => {
          const summaryItem = item as TableSummaryItem
          const spark = summaryItem.sparkline?.length ? (
            <SummarySparkline values={summaryItem.sparkline} label={summaryItem.sparklineLabel ?? summaryItem.label} />
          ) : null
          const slot = renderItem?.(summaryItem)
          if (!spark && !slot) return null
          return (
            <div className="flex min-w-0 flex-wrap items-center gap-2">
              {spark}
              {slot}
            </div>
          )
        }}
      />
    </div>
  )
}

/**
 * Stable column sort for a dense table.
 * Empty values stay last in both directions. Ties keep the original order.
 * Spanish collation is the default. The table never reads `meta`.
 */

export const SORT_DIRECTIONS = ["asc", "desc"] as const

export type SortDirection = (typeof SORT_DIRECTIONS)[number]

export type DataTableSort = {
  columnId: string
  direction: SortDirection
}

export type DataTableReorderLabels = {
  caption: string
  emptyTitle: string
  emptyHint: string
  loading: string
  errorTitle: string
  retry: string
  disabledNote: string
  announcements: string
  sortAscending: (column: string) => string
  sortDescending: (column: string) => string
  sorted: (column: string, direction: SortDirection) => string
  rowDetail: (label: string) => string
}

export const dataTableReorderLabels: DataTableReorderLabels = {
  caption: "Tabla",
  emptyTitle: "Nada que mostrar",
  emptyHint: "No hay filas con estos datos.",
  loading: "Cargando la tabla",
  errorTitle: "No se pudo mostrar la tabla",
  retry: "Reintentar",
  disabledNote: "La tabla está deshabilitada",
  announcements: "Avisos de la tabla",
  sortAscending: (column) => `Ordenar ${column} ascendente`,
  sortDescending: (column) => `Ordenar ${column} descendente`,
  sorted: (column, direction) => `Ordenado por ${column}, ${direction === "asc" ? "ascendente" : "descendente"}`,
  rowDetail: (label) => `Detalle de ${label}`,
}

export const dataTableReorderLabelsEn: DataTableReorderLabels = {
  caption: "Table",
  emptyTitle: "Nothing to show",
  emptyHint: "There are no rows for this data.",
  loading: "Loading the table",
  errorTitle: "The table could not be shown",
  retry: "Try again",
  disabledNote: "The table is disabled",
  announcements: "Table announcements",
  sortAscending: (column) => `Sort ${column} ascending`,
  sortDescending: (column) => `Sort ${column} descending`,
  sorted: (column, direction) => `Sorted by ${column}, ${direction === "asc" ? "ascending" : "descending"}`,
  rowDetail: (label) => `Details for ${label}`,
}

export function withTableLabels(labels?: Partial<DataTableReorderLabels>): DataTableReorderLabels {
  return { ...dataTableReorderLabels, ...labels }
}

export function nextSort(current: DataTableSort | null, columnId: string): DataTableSort {
  if (!current || current.columnId !== columnId || current.direction === "desc") {
    return { columnId, direction: "asc" }
  }
  return { columnId, direction: "desc" }
}

function isEmpty(value: string | number | null | undefined) {
  return value == null || value === ""
}

export function sortTableRows<T>(
  rows: readonly T[],
  read: (row: T) => string | number | null | undefined,
  direction: SortDirection,
  locale = "es-MX",
): T[] {
  return rows
    .map((row, index) => ({ row, index, value: read(row) }))
    .sort((a, b) => {
      const aEmpty = isEmpty(a.value)
      const bEmpty = isEmpty(b.value)
      if (aEmpty && bEmpty) return a.index - b.index
      if (aEmpty) return 1
      if (bEmpty) return -1
      const result =
        typeof a.value === "number" && typeof b.value === "number"
          ? a.value - b.value
          : String(a.value).localeCompare(String(b.value), locale, { numeric: true, sensitivity: "base" })
      if (result === 0) return a.index - b.index
      return direction === "asc" ? result : -result
    })
    .map((entry) => entry.row)
}

/** Points for a dense sparkline. One value draws a centered dot. */
export function sparklinePoints(values: readonly number[], width: number, height: number) {
  const finite = values.filter((value) => Number.isFinite(value))
  if (!finite.length || width <= 0 || height <= 0) return ""
  const min = Math.min(...finite)
  const max = Math.max(...finite)
  const span = max - min || 1
  return finite
    .map((value, index) => {
      const x = finite.length === 1 ? width / 2 : (index / (finite.length - 1)) * width
      const y = height - ((value - min) / span) * (height - 2) - 1
      return `${x.toFixed(2)},${y.toFixed(2)}`
    })
    .join(" ")
}
